//! Parity of this port's `level_db` against the JavaScript `levelDb`.
//!
//! The corpus is generated by `tools/gen-levels.mjs`, which runs the
//! reference `levelDb` over the 11 official presets and the neutral curve.
//! The JSON is gitignored like every other oracle: it is an artifact of the
//! AGPL sibling repo, never vendored here.
//!
//! Set `AURI_LEVEL_VALUES` to point at a corpus from elsewhere. Without one
//! the suite reports a skip and passes, so CI stays green with no sibling
//! checkout.

use std::path::PathBuf;

use auri_codec::Band;
use auri_gate::level_db;

use serde::Deserialize;

/// Relative tolerance for an f64 both sides computed with the same operations
/// (the ports are written expression-for-expression): far above the ulp noise
/// of `log10`, far below anything that could hide a real disagreement.
const EPS: f64 = 1e-9;

#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
struct Fixture {
    cases: Vec<Case>,
}

#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
struct Case {
    id: String,
    bands: serde_json::Value,
    preamp_db: f64,
    level_db: f64,
}

fn corpus_path() -> PathBuf {
    if let Ok(path) = std::env::var("AURI_LEVEL_VALUES") {
        return PathBuf::from(path);
    }
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures/level-values.json")
}

#[test]
fn every_level_matches_the_javascript_level_db() {
    let path = corpus_path();
    let Ok(text) = std::fs::read_to_string(&path) else {
        eprintln!(
            "SKIP level parity: {} not found (run `node tools/gen-levels.mjs`)",
            path.display()
        );
        return;
    };
    let fixture: Fixture = serde_json::from_str(&text).expect("the corpus parses");
    assert!(!fixture.cases.is_empty(), "the corpus contained nothing to compare");

    let mut worst = 0.0_f64;
    for case in &fixture.cases {
        let bands: Vec<Band> = serde_json::from_value(case.bands.clone())
            .unwrap_or_else(|error| panic!("[{}] bands do not deserialise: {error}", case.id));
        let got = level_db(&bands, case.preamp_db)
            .unwrap_or_else(|error| panic!("[{}] level_db refused: {error}", case.id));
        let scale = 1.0 + case.level_db.abs().max(got.abs());
        let delta = (got - case.level_db).abs() / scale;
        worst = worst.max(delta);
        assert!(
            delta <= EPS,
            "[{}] level_db {got} but the oracle says {} (relative delta {delta:e})",
            case.id,
            case.level_db
        );
    }

    eprintln!(
        "level parity: {} cases, worst relative delta {worst:e}",
        fixture.cases.len()
    );
}
